#!/usr/bin/env node
import { spawnSync } from "node:child_process";
import { mkdirSync, writeFileSync } from "node:fs";
import { homedir } from "node:os";
import { join } from "node:path";
import { fileURLToPath } from "node:url";

const DEFAULT_URL = "http://100.104.44.51:5173/b/default";
const CHECKOUT = join(homedir(), "development", "stallion");
const SHOTS_ROOT = join(homedir(), "development", ".tmp", "stallion-smoke");
const DEVICE = "Galaxy Tab S9";
const SCHEMES = ["light", "dark"];
const CLIP_PAD = 24;
const MIN_INK_RATIO = 0.01;

class SmokeFailure extends Error {}

const fail = (reason) => {
  throw new SmokeFailure(reason);
};

const run = (command, args, cwd) => {
  const result = spawnSync(command, args, { cwd, stdio: "inherit" });
  if (result.status !== 0) {
    fail(`${command} ${args.join(" ")} exited ${result.status ?? result.signal}`);
  }
};

const pull = () => {
  run("git", ["fetch", "origin"], CHECKOUT);
  run("git", ["merge", "--ff-only", "origin/main"], CHECKOUT);
  run("npm", ["ci", "--prefer-offline"], CHECKOUT);
};

const parseArgs = (argv) => {
  const flags = argv.filter((arg) => arg.startsWith("--"));
  const unknown = flags.filter((flag) => flag !== "--pull");
  if (unknown.length > 0) fail(`unknown flag ${unknown.join(", ")}; usage: smoke [--pull] [url]`);
  const [url = DEFAULT_URL] = argv.filter((arg) => !arg.startsWith("--"));
  return { url, pull: flags.includes("--pull") };
};

const REPO = fileURLToPath(new URL("..", import.meta.url));

const launch = async (chromium) => {
  const missing = await chromium.launch({ headless: true }).then(
    (browser) => ({ browser }),
    (error) => ({ error }),
  );
  if (missing.browser) return missing.browser;
  if (!/Executable doesn't exist/.test(String(missing.error?.message))) throw missing.error;
  run("npx", ["playwright", "install", "chromium-headless-shell"], REPO);
  return chromium.launch({ headless: true });
};

const strokePath = (viewport) => {
  const cx = viewport.width * (0.35 + Math.random() * 0.3);
  const cy = viewport.height * (0.45 + Math.random() * 0.25);
  return Array.from({ length: 24 }, (_, i) => {
    const t = i / 23;
    return { x: cx - 120 + t * 240, y: cy + Math.sin(t * Math.PI * 2) * 40 };
  });
};

const clipFor = (points) => {
  const xs = points.map((p) => p.x);
  const ys = points.map((p) => p.y);
  const x = Math.min(...xs) - CLIP_PAD;
  const y = Math.min(...ys) - CLIP_PAD;
  return {
    x,
    y,
    width: Math.max(...xs) + CLIP_PAD - x,
    height: Math.max(...ys) + CLIP_PAD - y,
  };
};

const drawWithTouch = async (page, points) => {
  const cdp = await page.context().newCDPSession(page);
  const touch = (type, point) =>
    cdp.send("Input.dispatchTouchEvent", {
      type,
      touchPoints: point ? [{ x: point.x, y: point.y, id: 1, radiusX: 2, radiusY: 2 }] : [],
    });
  const [first, ...rest] = points;
  await touch("touchStart", first);
  for (const point of rest) await touch("touchMove", point);
  await touch("touchEnd");
  await cdp.detach();
};

const countStoredRows = (page) =>
  page.evaluate(
    () =>
      new Promise((resolve, reject) => {
        const request = indexedDB.open("stallion");
        request.onerror = () => reject(request.error);
        request.onsuccess = () => {
          const db = request.result;
          const stores = [...db.objectStoreNames];
          if (stores.length === 0) {
            db.close();
            resolve({});
            return;
          }
          const tx = db.transaction(stores, "readonly");
          const counts = {};
          for (const name of stores) {
            const count = tx.objectStore(name).count();
            count.onsuccess = () => {
              counts[name] = count.result;
            };
          }
          tx.oncomplete = () => {
            db.close();
            resolve(counts);
          };
          tx.onerror = () => reject(tx.error);
        };
      }),
  );

const totalRows = (counts) => Object.values(counts).reduce((sum, n) => sum + n, 0);

const inkStats = (analyser, before, after) =>
  analyser.evaluate(
    async ([beforeB64, afterB64]) => {
      const pixels = async (b64) => {
        const bytes = Uint8Array.from(atob(b64), (c) => c.charCodeAt(0));
        const bitmap = await createImageBitmap(new Blob([bytes], { type: "image/png" }));
        const canvas = new OffscreenCanvas(bitmap.width, bitmap.height);
        const ctx = canvas.getContext("2d");
        ctx.drawImage(bitmap, 0, 0);
        return ctx.getImageData(0, 0, bitmap.width, bitmap.height).data;
      };
      const a = await pixels(beforeB64);
      const b = await pixels(afterB64);
      const distance = (p, i, q, j) =>
        Math.abs(p[i] - q[j]) + Math.abs(p[i + 1] - q[j + 1]) + Math.abs(p[i + 2] - q[j + 2]);
      let changed = 0;
      let offFirst = 0;
      for (let i = 0; i < b.length; i += 4) {
        if (distance(a, i, b, i) > 48) changed++;
        if (distance(b, 0, b, i) > 48) offFirst++;
      }
      return { changedRatio: changed / (b.length / 4), uniform: offFirst === 0 };
    },
    [before.toString("base64"), after.toString("base64")],
  );

const watchPage = (page, url) => {
  const problems = [];
  const origin = new URL(url).origin;
  const isFavicon404 = (target, status) => {
    const parsed = new URL(target);
    return status === 404 && parsed.origin === origin && parsed.pathname === "/favicon.ico";
  };
  page.on("console", (message) => {
    if (message.type() !== "error") return;
    const location = message.location().url;
    if (location && isFavicon404(location, 404) && /404/.test(message.text())) return;
    problems.push(`console error: ${message.text()}`);
  });
  page.on("pageerror", (error) => problems.push(`page error: ${error.message}`));
  page.on("requestfailed", (request) => {
    if (new URL(request.url()).pathname === "/favicon.ico") return;
    problems.push(`request failed: ${request.url()} (${request.failure()?.errorText})`);
  });
  page.on("response", (response) => {
    if (response.status() < 400 || isFavicon404(response.url(), response.status())) return;
    problems.push(`HTTP ${response.status()}: ${response.url()}`);
  });
  return problems;
};

const waitForBoard = async (page) => {
  await page.locator("canvas.surface").waitFor({ state: "visible", timeout: 15000 });
  await page.waitForFunction(() => {
    const element = document.querySelector("canvas.surface");
    return element instanceof HTMLCanvasElement && element.width > 0 && element.height > 0;
  });
  const alert = page.locator("[role=alert]");
  if (await alert.isVisible()) fail(`board shows an error: ${(await alert.innerText()).trim()}`);
};

const smokeScheme = async ({ browser, devices, analyser, url, scheme, dir }) => {
  const context = await browser.newContext({ ...devices[DEVICE], colorScheme: scheme });
  const page = await context.newPage();
  const problems = watchPage(page, url);
  const shot = async (name, clip) => {
    const path = join(dir, `${scheme}-${name}.png`);
    const buffer = await page.screenshot(clip ? { clip } : {});
    writeFileSync(path, buffer);
    return { path, buffer };
  };
  const check = () => {
    if (problems.length > 0) fail(`${scheme}: ${problems[0]}`);
  };
  try {
    await page.goto(url, { waitUntil: "load" });
    await waitForBoard(page);
    await page.waitForTimeout(500);
    check();
    const viewport = page.viewportSize() ?? fail("no viewport");
    const points = strokePath(viewport);
    const clip = clipFor(points);
    const rowsBefore = totalRows(await countStoredRows(page));
    const blank = await shot("before", clip);

    await drawWithTouch(page, points);
    await page.waitForTimeout(800);
    const drawn = await shot("drawn", clip);
    const full = await shot("drawn-full");
    const drawnInk = await inkStats(analyser, blank.buffer, drawn.buffer);
    if (drawnInk.uniform) fail(`${scheme}: canvas is one colour after drawing (invisible ink)`);
    if (drawnInk.changedRatio < MIN_INK_RATIO) fail(`${scheme}: stroke did not show on the canvas`);
    check();

    await page.reload({ waitUntil: "load" });
    await waitForBoard(page);
    await page.waitForTimeout(1000);
    const counts = await countStoredRows(page);
    const rowsAfter = totalRows(counts);
    if (rowsAfter === 0) fail(`${scheme}: nothing stored in IndexedDB after reload`);
    if ((counts.objects ?? 0) > 0 && rowsAfter <= rowsBefore) {
      fail(`${scheme}: stroke not stored, ${rowsBefore} rows before and ${rowsAfter} after`);
    }
    const reloaded = await shot("reloaded", clip);
    const reloadedInk = await inkStats(analyser, blank.buffer, reloaded.buffer);
    if (reloadedInk.changedRatio < MIN_INK_RATIO) fail(`${scheme}: stroke gone after reload`);
    check();
    return {
      scheme,
      rows: counts,
      ink: Number(drawnInk.changedRatio.toFixed(3)),
      screenshots: [blank.path, drawn.path, full.path, reloaded.path],
    };
  } finally {
    await context.close();
  }
};

const main = async () => {
  const options = parseArgs(process.argv.slice(2));
  if (options.pull) pull();
  const { chromium, devices } = await import("playwright");
  const dir = join(SHOTS_ROOT, new Date().toISOString().replace(/[:.]/g, "-"));
  mkdirSync(dir, { recursive: true });
  const browser = await launch(chromium);
  try {
    const analyser = await browser.newPage();
    for (const scheme of SCHEMES) {
      const result = await smokeScheme({
        browser,
        devices,
        analyser,
        url: options.url,
        scheme,
        dir,
      });
      console.log(`PASS ${result.scheme}: ink ${result.ink}, rows ${JSON.stringify(result.rows)}`);
      for (const path of result.screenshots) console.log(`  ${path}`);
    }
  } finally {
    await browser.close();
  }
  console.log(`smoke passed: ${options.url} (${dir})`);
};

main().catch((error) => {
  const reason = error instanceof SmokeFailure ? error.message : String(error?.message ?? error);
  console.error(`smoke failed: ${reason.split("\n")[0]}`);
  process.exit(1);
});
#!/usr/bin/env node
import { spawnSync } from "node:child_process";
import { randomBytes } from "node:crypto";
import { mkdirSync, rmSync } from "node:fs";
import { homedir } from "node:os";
import { join } from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = join(homedir(), "development", ".tmp", "stallion-duo");
const VIEWPORT = { width: 1280, height: 800 };
const BLUE = { label: "Colour 5", rgb: [0x00, 0x90, 0xff] };
const RED = { label: "Colour 2", rgb: [0xe5, 0x48, 0x4d] };
const B_DELAY_MS = 2000;
const SETTLE_MS = 3000;
const MIN_INK_PIXELS = 200;
const STEP_MS = 12;
const REPO = fileURLToPath(new URL("..", import.meta.url));

class DemoFailure extends Error {}

const fail = (reason) => {
  throw new DemoFailure(reason);
};

const usage = "usage: demo:duo <url> [--board <id>]";

const parseArgs = (argv) => {
  const rest = [...argv];
  let board;
  let url;
  while (rest.length > 0) {
    const arg = rest.shift();
    if (arg === "--board") {
      board = rest.shift() ?? fail(`--board needs an id; ${usage}`);
      continue;
    }
    if (arg.startsWith("--")) fail(`unknown flag ${arg}; ${usage}`);
    if (url) fail(`unexpected argument ${arg}; ${usage}`);
    url = arg;
  }
  if (!url) fail(`missing url; ${usage}`);
  const target = new URL(url);
  target.pathname = `/b/${encodeURIComponent(board ?? `duo-${randomBytes(4).toString("hex")}`)}`;
  return { url: target.toString() };
};

const launch = async (chromium) => {
  const first = await chromium.launch({ headless: true }).then(
    (browser) => ({ browser }),
    (error) => ({ error }),
  );
  if (first.browser) return first.browser;
  if (!/Executable doesn't exist/.test(String(first.error?.message))) throw first.error;
  const install = spawnSync("npx", ["playwright", "install", "chromium-headless-shell", "ffmpeg"], {
    cwd: REPO,
    stdio: "inherit",
  });
  if (install.status !== 0) fail("playwright install failed");
  return chromium.launch({ headless: true });
};

const watchPage = (name, page, url) => {
  const problems = [];
  const origin = new URL(url).origin;
  const isFavicon = (target) => {
    const parsed = new URL(target);
    return parsed.origin === origin && parsed.pathname === "/favicon.ico";
  };
  page.on("console", (message) => {
    if (message.type() !== "error") return;
    const location = message.location().url;
    if (location && isFavicon(location) && /404/.test(message.text())) return;
    problems.push(`${name} console error: ${message.text()}`);
  });
  page.on("pageerror", (error) => problems.push(`${name} page error: ${error.message}`));
  page.on("response", (response) => {
    if (response.status() < 400) return;
    if (response.status() === 404 && isFavicon(response.url())) return;
    problems.push(`${name} HTTP ${response.status()}: ${response.url()}`);
  });
  return problems;
};

const openBoard = async (page, url, colour) => {
  await page.goto(url, { waitUntil: "load" });
  await page.locator("canvas.surface").waitFor({ state: "visible", timeout: 15000 });
  await page.getByRole("button", { name: "Large pencil" }).click();
  await page.getByRole("button", { name: colour.label, exact: true }).click();
};

const circle = (cx, cy, r, turns = 1, start = 0) =>
  Array.from({ length: Math.round(90 * turns) + 1 }, (_, i) => {
    const angle = start + (i / 90) * Math.PI * 2;
    return { x: cx + Math.cos(angle) * r, y: cy + Math.sin(angle) * r };
  });

const spiral = (cx, cy, from, to, turns) => {
  const count = Math.round(90 * turns);
  return Array.from({ length: count + 1 }, (_, i) => {
    const t = i / count;
    const angle = t * turns * Math.PI * 2;
    const r = from + (to - from) * t;
    return { x: cx + Math.cos(angle) * r, y: cy + Math.sin(angle) * r };
  });
};

const square = (cx, cy, half) => {
  const corners = [
    [cx - half, cy - half],
    [cx + half, cy - half],
    [cx + half, cy + half],
    [cx - half, cy + half],
    [cx - half, cy - half],
  ];
  return corners.slice(1).flatMap(([x, y], i) => {
    const [px, py] = corners[i];
    return Array.from({ length: 30 }, (_, j) => ({
      x: px + ((x - px) * (j + 1)) / 30,
      y: py + ((y - py) * (j + 1)) / 30,
    }));
  });
};

const draw = async (page, points) => {
  const [first, ...rest] = points;
  await page.mouse.move(first.x, first.y);
  await page.mouse.down();
  for (const point of rest) {
    await page.mouse.move(point.x, point.y);
    await page.waitForTimeout(STEP_MS);
  }
  await page.mouse.up();
};

const inkPixels = (page, colour) =>
  page.evaluate(([r, g, b]) => {
    const canvas = document.querySelector("canvas.surface");
    if (!(canvas instanceof HTMLCanvasElement)) return -1;
    const context = canvas.getContext("2d");
    if (!context) return -1;
    const { data } = context.getImageData(0, 0, canvas.width, canvas.height);
    let count = 0;
    for (let i = 0; i < data.length; i += 4) {
      const distance =
        Math.abs(data[i] - r) + Math.abs(data[i + 1] - g) + Math.abs(data[i + 2] - b);
      if (data[i + 3] > 200 && distance < 60) count++;
    }
    return count;
  }, colour.rgb);

const connection = (page) =>
  page
    .locator(".status[data-connection]")
    .getAttribute("data-connection", { timeout: 5000 })
    .then((value) => value ?? "missing");

const combine = (a, b, out) => {
  const which = spawnSync("ffmpeg", ["-version"], { stdio: "ignore" });
  if (which.status !== 0) return undefined;
  const result = spawnSync(
    "ffmpeg",
    [
      "-y",
      "-loglevel",
      "error",
      "-i",
      a,
      "-i",
      b,
      "-filter_complex",
      "[0:v]scale=960:600[l];[1:v]scale=960:600[r];[l][r]hstack=inputs=2,format=yuv420p[v]",
      "-map",
      "[v]",
      "-c:v",
      "libx264",
      "-crf",
      "23",
      out,
    ],
    { stdio: "inherit" },
  );
  return result.status === 0 ? out : undefined;
};

const main = async () => {
  const { url } = parseArgs(process.argv.slice(2));
  const { chromium } = await import("playwright");
  const dir = join(ROOT, new Date().toISOString().replace(/[:.]/g, "-"));
  const raw = join(dir, "raw");
  mkdirSync(raw, { recursive: true });
  const browser = await launch(chromium);
  const failures = [];
  const artifacts = [];
  const contextOptions = { viewport: VIEWPORT, recordVideo: { dir: raw, size: VIEWPORT } };
  const contextA = await browser.newContext(contextOptions);
  const contextB = await browser.newContext(contextOptions);
  const a = await contextA.newPage();
  const b = await contextB.newPage();
  const problemsA = watchPage("A", a, url);
  const problemsB = watchPage("B", b, url);
  const cx = VIEWPORT.width / 2;
  const cy = VIEWPORT.height / 2 + 40;
  try {
    const runA = (async () => {
      await openBoard(a, url, BLUE);
      await draw(a, circle(cx, cy, 280, 1.02, -Math.PI / 2));
      await draw(a, square(cx, cy, 170));
    })();
    const runB = (async () => {
      await b.waitForTimeout(B_DELAY_MS);
      await openBoard(b, url, RED);
      await draw(b, spiral(cx, cy, 20, 300, 3));
    })();
    await Promise.all([runA, runB]);
    await Promise.all([a.waitForTimeout(SETTLE_MS), b.waitForTimeout(SETTLE_MS)]);
    for (const [name, page] of [
      ["a", a],
      ["b", b],
    ]) {
      const path = join(dir, `${name}.png`);
      await page.screenshot({ path });
      artifacts.push(path);
    }
    const redOnA = await inkPixels(a, RED);
    const blueOnB = await inkPixels(b, BLUE);
    if (redOnA < MIN_INK_PIXELS) failures.push(`A shows ${redOnA} red pixels`);
    if (blueOnB < MIN_INK_PIXELS) failures.push(`B shows ${blueOnB} blue pixels`);
    const [statusA, statusB] = await Promise.all([connection(a), connection(b)]);
    if (statusA !== "Connected") failures.push(`A status is ${statusA}`);
    if (statusB !== "Connected") failures.push(`B status is ${statusB}`);
    const own = `blue on A ${await inkPixels(a, BLUE)} px, red on B ${await inkPixels(b, RED)} px`;
    console.log(`ink: red on A ${redOnA} px, blue on B ${blueOnB} px (${own})`);
  } catch (error) {
    failures.push(String(error?.message ?? error).split("\n")[0]);
  } finally {
    await contextA.close();
    await contextB.close();
  }
  const videoA = join(dir, "a.webm");
  const videoB = join(dir, "b.webm");
  await a.video()?.saveAs(videoA);
  await b.video()?.saveAs(videoB);
  await browser.close();
  rmSync(raw, { recursive: true, force: true });
  const combined = combine(videoA, videoB, join(dir, "combined.mp4"));
  failures.push(...problemsA, ...problemsB);
  console.log(`board: ${url}`);
  for (const path of [videoA, videoB, combined, ...artifacts].filter(Boolean)) {
    console.log(`  ${path}`);
  }
  if (failures.length > 0) fail(failures.join("; "));
  console.log(`duo demo passed (${dir})`);
};

main().catch((error) => {
  const reason = error instanceof DemoFailure ? error.message : String(error?.message ?? error);
  console.error(`duo demo failed: ${reason.split("\n")[0]}`);
  process.exit(1);
});
