    fn reads_the_header_before_the_cookie() {
        assert_eq!(token(Some("h"), Some("CF_Authorization=c")), Some("h"));
        assert_eq!(token(None, Some("a=1; CF_Authorization=c")), Some("c"));
        assert_eq!(token(None, Some("a=1")), None);
    }
